from rope import Rope, REST_LENGTH


def test_segment_lengths_within_1_percent():
    r = simulate(300)
    for i in range(r.n - 1):
        dx = r.pos[i + 1][0] - r.pos[i][0]
        dy = r.pos[i + 1][1] - r.pos[i][1]
        length = (dx * dx + dy * dy) ** 0.5
        assert abs(length - REST_LENGTH) <= 0.01 * REST_LENGTH, (
            f"segment {i} length {length} deviates >1% from rest length"
        )


def test_total_length_within_2_percent_of_95():
    r = simulate(300)
    total = sum(
        ((r.pos[i + 1][0] - r.pos[i][0]) ** 2 +
         (r.pos[i + 1][1] - r.pos[i][1]) ** 2) ** 0.5
        for i in range(r.n - 1)
    )
    assert abs(total - 95.0) <= 0.02 * 95.0, f"total length {total}"


def test_pinned_particle_never_moved():
    r = Rope()
    assert r.pos[0] == (0.0, 0.0)
    for _ in range(300):
        r.tick()
        assert r.pos[0] == (0.0, 0.0), "pin moved during simulation"


def test_bottom_particle_hangs_below_pin():
    r = simulate(300)
    bottom_x = r.pos[-1][0]
    assert abs(bottom_x - r.pos[0][0]) < 1e-3, f"bottom x offset {bottom_x}"
    assert bottom_x >= 0.0  # directly below, never above


def simulate(ticks):
    r = Rope()
    for _ in range(ticks):
        r.tick()
    return r

